import { test } from "node:test";
import assert from "node:assert/strict";
import { centerOfMass, resampleToGrid, preprocess, normalizePolarity, GRID } from "./preprocess.js";

test("white-background handwriting is inverted so ink is bright", () => {
  // 26x26 white canvas with a dark stroke: border ring is bright.
  const img = new Array(26 * 26).fill(255);
  for (let y = 4; y < 22; y++) {
    for (let x = 11; x < 15; x++) img[y * 26 + x] = 30;
  }
  const out = preprocess(img, 26, 26);
  assert.ok(out[0] < 0.1, "corner should be background");
  assert.ok(Math.max(...out) > 0.5, "stroke ink should survive");
});

test("dark-background image is not inverted", () => {
  const img = new Array(26 * 26).fill(0);
  for (let y = 4; y < 22; y++) {
    for (let x = 11; x < 15; x++) img[y * 26 + x] = 200;
  }
  const out = preprocess(img, 26, 26);
  assert.ok(out[0] < 0.1);
  assert.ok(Math.max(...out) > 0.5);
});

test("zero image center of mass is canvas center", () => {
  const img = new Uint8Array(26 * 26);
  const [cx, cy] = centerOfMass(img, 26, 26);
  assert.ok(Math.abs(cx - 12.5) < 1e-9);
  assert.ok(Math.abs(cy - 12.5) < 1e-9);
});

test("single bright pixel center of mass is at pixel", () => {
  const img = new Uint8Array(26 * 26);
  img[5 * 26 + 9] = 255;
  const [cx, cy] = centerOfMass(img, 26, 26);
  assert.ok(Math.abs(cx - 9.0) < 1e-9);
  assert.ok(Math.abs(cy - 5.0) < 1e-9);
});

test("resampled center of mass is grid center", () => {
  const img = new Uint8Array(52 * 52);
  for (let y = 10; y < 40; y++) {
    img[y * 52 + 10] = 200;
    img[y * 52 + 11] = 200;
  }
  const out = preprocess(img, 52, 52);
  assert.equal(out.length, 256);
  const [cx, cy] = centerOfMassF64(out, GRID, GRID);
  assert.ok(Math.abs(cx - 7.5) < 0.51, `cx = ${cx}`);
  assert.ok(Math.abs(cy - 7.5) < 0.51, `cy = ${cy}`);
});

test("output is normalized 0 to 1", () => {
  const img = new Uint8Array(16 * 16);
  for (let i = 0; i < img.length; i++) img[i] = i % 256;
  const out = preprocess(img, 16, 16);
  for (const v of out) assert.ok(v >= 0.0 && v <= 1.0);
});

// Local f64 variant for verifying the output grid (mirrors Rust's helper).
function centerOfMassF64(img, w, h) {
  let sum = 0, sx = 0, sy = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const v = img[y * w + x];
      sum += v;
      sx += x * v;
      sy += y * v;
    }
  }
  if (sum === 0) return [(w - 1) / 2, (h - 1) / 2];
  return [sx / sum, sy / sum];
}

