// Parity golden values generated from the Rust implementation (printed with
// {:e} precision). The JS engine must match within 1e-9 to keep the two
// teaching engines interchangeable.
test("cross-language parity with Rust golden values", () => {
  const img5 = new Uint8Array(25);
  for (let i = 0; i < 5; i++) {
    img5[i * 5 + i] = 255;
    img5[i * 5 + 4 - i] = 128;
  }
  const out5 = preprocess(img5, 5, 5);
  assert.equal(out5.length, GOLD_5x5.length);
  for (let i = 0; i < out5.length; i++) {
    assert.ok(Math.abs(out5[i] - GOLD_5x5[i]) < 1e-9, "5x5[" + i + "]: " + out5[i] + " vs " + GOLD_5x5[i]);
  }

  const img26 = new Uint8Array(26 * 26);
  for (let y = 0; y < 26; y++) {
    for (let x = 0; x < 26; x++) {
      const dx = x - 13, dy = y - 13;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d < 6) img26[y * 26 + x] = Math.floor(255 * (1 - d / 6));
    }
  }
  const out26 = preprocess(img26, 26, 26);
  assert.equal(out26.length, GOLD_26x26.length);
  for (let i = 0; i < out26.length; i++) {
    assert.ok(Math.abs(out26[i] - GOLD_26x26[i]) < 1e-9, "26x26[" + i + "]: " + out26[i] + " vs " + GOLD_26x26[i]);
  }
});
